/**
 * Shared live train time calculation and timeline grouping utilities.
 */

export function getHaltTime(arr?: string, dep?: string): number {
  if (!arr || !dep || arr === '--:--' || dep === '--:--') return 0;
  try {
    const [arrH, arrM] = arr.split(':').map(Number);
    const [depH, depM] = dep.split(':').map(Number);
    if (isNaN(arrH) || isNaN(arrM) || isNaN(depH) || isNaN(depM)) return 0;

    const arrMinutes = arrH * 60 + arrM;
    let depMinutes = depH * 60 + depM;
    if (depMinutes < arrMinutes) {
      depMinutes += 24 * 60;
    }
    return depMinutes - arrMinutes;
  } catch {
    return 0;
  }
}

export function addMinutesToTime(timeStr?: string, minutes?: number): string {
  if (!timeStr || timeStr === '--:--') return 'Unknown';
  if (!minutes || minutes <= 0) return timeStr;
  try {
    const [h, m] = timeStr.split(':').map(Number);
    if (isNaN(h) || isNaN(m)) return timeStr;

    const totalMinutes = h * 60 + m + minutes;
    const finalH = Math.floor(totalMinutes / 60) % 24;
    const finalM = totalMinutes % 60;

    const pad = (n: number) => String(n).padStart(2, '0');
    return `${pad(finalH)}:${pad(finalM)}`;
  } catch {
    return timeStr;
  }
}

export type TimelineSegment<T> =
  | { kind: 'halt'; stop: T; originalIndex: number }
  | { kind: 'passthrough_group'; id: string; stops: Array<{ stop: T; originalIndex: number }> };

/**
 * Groups consecutive non-halting (`is_halt === false`, and not currently occupied)
 * pass-through stations between commercial halts so UIs can render collapsible clusters.
 */
export function groupTimelinePassThrough<T extends { is_halt?: boolean; status?: string; is_current?: boolean }>(
  stops: T[]
): TimelineSegment<T>[] {
  const segments: TimelineSegment<T>[] = [];
  let buffer: Array<{ stop: T; originalIndex: number }> = [];

  const flush = () => {
    if (buffer.length > 0) {
      segments.push({
        kind: 'passthrough_group',
        id: `pt-${buffer[0].originalIndex}-${buffer[buffer.length - 1].originalIndex}`,
        stops: buffer,
      });
      buffer = [];
    }
  };

  stops.forEach((stop, idx) => {
    const isCurrent = stop.is_current === true || stop.status === 'current' || stop.status === 'CURRENT';
    const isNonHalt = stop.is_halt === false && !isCurrent;
    if (isNonHalt) {
      buffer.push({ stop, originalIndex: idx });
    } else {
      flush();
      segments.push({ kind: 'halt', stop, originalIndex: idx });
    }
  });
  flush();

  return segments;
}
